import { line } from 'axylo';

/**
 * Options for the "Daily visits" line chart.
 *
 * - `day` holds UTC midnights ('2026-03-01T00:00:00Z'). Declaring `type: 'date'` reads each one as its
 *   UTC calendar day, the same in every time zone; left as instants they would show a day early for
 *   viewers west of UTC (AX111).
 * - Rows may arrive in any order: Axylo sorts dated rows by x, so they are passed through untouched and
 *   diagnostics and events keep referring to the caller's own rows.
 * - Days with no row are not invented: on a regular daily series Axylo draws them as gaps (hint AX105),
 *   never as zero and never joined across.
 *
 * @param {readonly { day: string, visits: number | null }[]} data rows from data.json
 */
export function chartOptions(data) {
  return {
    title: 'Daily visits',
    data,
    x: { field: 'day', type: 'date' },
    y: { field: 'visits', label: 'Visits' },
  };
}

/**
 * Draws daily visits as a line chart into `element`.
 *
 * @param {HTMLElement} element the chart container
 * @param {readonly { day: string, visits: number | null }[]} data rows from data.json
 * @returns the Axylo chart handle
 */
export default function render(element, data) {
  return line(element, chartOptions(data));
}

