input.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { chartOptions } from './chart.js';

const rows = JSON.parse(readFileSync('data.json', 'utf8'));
console.log('default export is function render, arity', typeof render, render.name, render.length);
console.log('rows:', rows.length);

const problems = validate('line', chartOptions(rows));
console.log('--- chart.js options:', problems.length, 'diagnostic(s)');
for (const d of problems) console.log(d.code, d.level, d.field ?? '', '|', d.message);
const blocking = problems.filter(d => d.level !== 'hint');
console.log('blocking (error/warning):', blocking.length);

const control = validate('line', { ...chartOptions(rows), x: 'day' });
console.log('--- control without type date:');
for (const d of control) console.log(d.code, d.level, '|', d.message);
"

